const j = $json;
const pick = (k, label) => (j[k] !== undefined ? j[k] : (j[label] !== undefined ? j[label] : ''));
const errors = [];
const fullName = String(pick('full_name', 'Full name (as on PAN)')).trim().replace(/ +/g, ' ');
const pan = String(pick('pan', 'PAN number')).trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
const aadhaar4 = String(pick('aadhaar_last4', 'Last 4 digits of Aadhaar')).replace(/[^0-9]/g, '');
const email = String(pick('email', 'Email')).trim().toLowerCase();
const mobile = String(pick('mobile', 'Mobile number')).replace(/[^0-9]/g, '').slice(-10);
const dobRaw = String(pick('dob', 'Date of birth')).slice(0, 10);

if (!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(pan)) errors.push('PAN number format is invalid (expected AAAAA9999A)');
else if (pan.charAt(3) !== 'P') errors.push('PAN does not belong to an individual (4th character must be P)');
if (!/^[0-9]{4}$/.test(aadhaar4)) errors.push('Aadhaar last 4 digits are invalid');
if (!/^[^@ ]+@[^@ ]+[.][^@ ]+$/.test(email)) errors.push('Email address is invalid');
if (!/^[6-9][0-9]{9}$/.test(mobile)) errors.push('Mobile number is invalid');
if (fullName.split(' ').length < 2) errors.push('Full name must include first and last name');

let age = null;
const dob = new Date(dobRaw);
if (isNaN(dob.getTime())) {
  errors.push('Date of birth is invalid');
} else {
  age = Math.floor((Date.now() - dob.getTime()) / 31557600000);
  if (age < 18) errors.push('Applicant must be at least 18 years old');
  if (age > 100) errors.push('Date of birth looks implausible');
}

const binKeys = Object.keys($input.item.binary || {});
if (binKeys.length === 0) errors.push('PAN card image is missing');

const appId = 'KYC-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();

return {
  json: {
    application_id: appId,
    submitted_at: j.submittedAt || new Date().toISOString(),
    full_name: fullName,
    first_name: fullName.split(' ')[0],
    dob: dobRaw,
    age: age,
    pan: pan,
    pan_masked: pan.length === 10 ? pan.slice(0, 2) + 'XXXXX' + pan.slice(7) : pan,
    aadhaar_masked: 'XXXX-XXXX-' + aadhaar4,
    email: email,
    mobile: mobile,
    address: String(pick('address', 'Residential address')).trim(),
    nationality: String(pick('nationality', 'Nationality')),
    occupation: String(pick('occupation', 'Occupation')),
    annual_income: String(pick('annual_income', 'Annual income')),
    source_of_funds: String(pick('source_of_funds', 'Primary source of funds')),
    pep_declared: String(pick('pep', 'Are you or a close relative a Politically Exposed Person (PEP)?')) === 'Yes',
    validation_errors: errors,
    input_valid: errors.length === 0
  },
  binary: binKeys.length ? { id_doc: $input.item.binary[binKeys[0]] } : {}
};

const app = $('Validate Inputs & Prepare Document').item.json;
const doc = ($json && $json.output) ? $json.output : null;

const norm = s => String(s || '').toUpperCase().replace(/[^A-Z ]/g, ' ').replace(/ +/g, ' ').trim();
const lev = (a, b) => {
  const m = a.length, n = b.length, d = [];
  for (let i = 0; i <= m; i++) d[i] = [i];
  for (let k = 1; k <= n; k++) d[0][k] = k;
  for (let i = 1; i <= m; i++) for (let k = 1; k <= n; k++)
    d[i][k] = Math.min(d[i - 1][k] + 1, d[i][k - 1] + 1, d[i - 1][k - 1] + (a[i - 1] === b[k - 1] ? 0 : 1));
  return d[m][n];
};
const sim = (a, b) => {
  const x = norm(a).split(' ').sort().join(' ');
  const y = norm(b).split(' ').sort().join(' ');
  if (!x || !y) return 0;
  return 1 - lev(x, y) / Math.max(x.length, y.length);
};
const round2 = v => Math.round(v * 100) / 100;

const flags = [];
let score = 0;
const add = (flag, points) => { flags.push(flag); score += points; };

let nameScore = null, dobMatch = null, panMatch = null;
if (!doc) {
  add('DOC_EXTRACTION_FAILED', 40);
} else {
  if (!doc.is_government_id) add('NOT_A_GOVT_ID', 40);
  nameScore = round2(sim(app.full_name, doc.name_on_document));
  if (nameScore < 0.85) add('NAME_MISMATCH', 25);
  else if (nameScore < 0.95) add('NAME_MINOR_VARIATION', 5);
  dobMatch = String(doc.dob_on_document || '').slice(0, 10) === app.dob;
  if (!dobMatch) add('DOB_MISMATCH', 25);
  panMatch = String(doc.id_number || '').toUpperCase().replace(/[^A-Z0-9]/g, '') === app.pan;
  if (!panMatch) add('PAN_MISMATCH', 30);
  const tamper = (doc.tampering_signals || []).filter(t => t && String(t).toLowerCase() !== 'none');
  if (tamper.length) add('POSSIBLE_TAMPERING: ' + tamper.join('; '), 30);
  if (Number(doc.legibility) < 0.6) add('LOW_LEGIBILITY', 15);
  if (Number(doc.extraction_confidence) < 0.7) add('LOW_EXTRACTION_CONFIDENCE', 10);
}

// DEMO watchlist (fictional names). In production replace with an HTTP Request to OpenSanctions / Refinitiv World-Check / Dow Jones / LexisNexis.
const WATCHLIST = [
  { name: 'Viktor Aleksandrovich Morozov', list: 'DEMO-OFAC-SDN', type: 'SANCTION', dob: '1968-03-14' },
  { name: 'Imran Rashid Qureshi', list: 'DEMO-UN-1267', type: 'SANCTION', dob: '1975-11-02' },
  { name: 'Chen Wei Long', list: 'DEMO-EU-CFSP', type: 'SANCTION', dob: '' },
  { name: 'Daniel Okafor Mensah', list: 'DEMO-INTERPOL-RED', type: 'SANCTION', dob: '1981-06-30' },
  { name: 'Arvind Prakash Bhandari', list: 'DEMO-PEP-STATE-MINISTER', type: 'PEP', dob: '1962-01-19' }
];
const hits = [];
for (const w of WATCHLIST) {
  const s = sim(app.full_name, w.name);
  if (s >= 0.85) {
    const dobCorroborated = w.dob ? w.dob === app.dob : null;
    const strength = (dobCorroborated === true || s >= 0.95) ? 'STRONG' : (dobCorroborated === false ? 'WEAK_DOB_DIFFERS' : 'POSSIBLE');
    hits.push({ watchlist_name: w.name, list: w.list, type: w.type, similarity: round2(s), dob_corroborated: dobCorroborated, strength: strength });
  }
}
if (hits.some(h => h.strength === 'STRONG')) add('WATCHLIST_STRONG_MATCH', 60);
else if (hits.length) add('WATCHLIST_POSSIBLE_MATCH', 35);

if (app.pep_declared) add('PEP_SELF_DECLARED', 30);
if (app.nationality !== 'Indian') add('NON_RESIDENT_EDD_REQUIRED', 10);
if (app.occupation === 'Student' && ['Rs 25 lakh - 1 crore', 'Above Rs 1 crore'].includes(app.annual_income)) add('INCOME_PROFILE_INCONSISTENT', 15);
if (app.source_of_funds === 'Other') add('UNCLEAR_SOURCE_OF_FUNDS', 5);
if (app.validation_errors.length) add('INPUT_VALIDATION_FAILED', 20);

return {
  json: {
    ...app,
    document_extraction: doc,
    name_match_score: nameScore,
    dob_match: dobMatch,
    pan_match: panMatch,
    screening_hits: hits,
    rule_flags: flags,
    rule_score: Math.min(score, 100)
  }
};

const f = $('Cross-Check & Sanctions Screening').item.json;
const ai = ($json && $json.output) ? $json.output : {};
const aiAvailable = Number.isFinite(Number(ai.ai_risk_score));
const aiScore = aiAvailable ? Number(ai.ai_risk_score) : 100;
const finalScore = Math.min(100, Math.max(f.rule_score, aiScore));
const level = finalScore < 30 ? 'LOW' : (finalScore < 60 ? 'MEDIUM' : 'HIGH');
const docProblem = f.rule_flags.some(x => ['DOC_EXTRACTION_FAILED', 'NOT_A_GOVT_ID', 'LOW_LEGIBILITY'].includes(x));

let decision, reason;
if (f.screening_hits.length > 0) {
  decision = 'MANUAL_REVIEW'; reason = 'Potential watchlist match - only a human can disposition this';
} else if (f.validation_errors.length > 0 || docProblem) {
  decision = 'REQUEST_INFO'; reason = 'Incomplete, invalid or unreadable submission';
} else if (!aiAvailable || f.pep_declared || ai.recommended_action !== 'APPROVE' || finalScore >= 30) {
  decision = 'MANUAL_REVIEW'; reason = 'Risk signals need analyst judgement';
} else {
  decision = 'AUTO_APPROVE'; reason = 'All checks passed with low risk (straight-through processing)';
}

const started = new Date(f.submitted_at).getTime();
const processingMs = isNaN(started) ? null : Date.now() - started;

const esc = s => String(s === null || s === undefined ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const row = (k, v) => '<tr><td style="padding:6px 10px;color:#555;border-bottom:1px solid #eee">' + k + '</td><td style="padding:6px 10px;border-bottom:1px solid #eee"><b>' + v + '</b></td></tr>';
const doc = f.document_extraction || {};
const hitsHtml = f.screening_hits.length
  ? f.screening_hits.map(h => esc(h.watchlist_name) + ' [' + esc(h.list) + '] similarity ' + h.similarity + ', DOB corroborated: ' + h.dob_corroborated + ' (' + h.strength + ')').join('<br>')
  : 'None';
const reviewerHtml = '<div style="font-family:Arial,sans-serif;max-width:680px">'
  + '<h2 style="margin:0 0 4px">KYC case ' + esc(f.application_id) + ' needs your review</h2>'
  + '<p style="color:#555;margin:0 0 12px">Routed to manual review: ' + esc(reason) + '</p>'
  + '<table style="border-collapse:collapse;width:100%">'
  + row('Applicant', esc(f.full_name) + ' (age ' + esc(f.age) + ')')
  + row('PAN / Aadhaar', esc(f.pan_masked) + ' / ' + esc(f.aadhaar_masked))
  + row('Profile', esc(f.occupation) + ', ' + esc(f.annual_income) + ', funds: ' + esc(f.source_of_funds) + ', ' + esc(f.nationality))
  + row('PEP self-declared', f.pep_declared ? 'YES' : 'No')
  + row('Document read', esc(doc.document_type) + ' - name "' + esc(doc.name_on_document) + '", DOB ' + esc(doc.dob_on_document) + ', ID ' + esc(doc.id_number))
  + row('Name match score', esc(f.name_match_score))
  + row('DOB / PAN match', esc(f.dob_match) + ' / ' + esc(f.pan_match))
  + row('Watchlist screening', hitsHtml)
  + row('Rule flags', esc(f.rule_flags.join(', ') || 'None'))
  + row('Risk', level + ' (' + finalScore + '/100; rules ' + f.rule_score + ', AI ' + (aiAvailable ? aiScore : 'n/a') + ')')
  + row('AI recommendation', esc(ai.recommended_action || 'n/a'))
  + row('AI rationale', esc(ai.rationale || 'AI assessment unavailable'))
  + '</table><p style="color:#888;font-size:12px">The AI recommends; you decide. Your decision is written to the audit trail.</p></div>';

const friendly = {
  DOC_EXTRACTION_FAILED: 'We could not read the uploaded document. Please upload a clear photo of your PAN card.',
  NOT_A_GOVT_ID: 'The uploaded file does not appear to be a PAN card. Please upload a photo of your original PAN card.',
  LOW_LEGIBILITY: 'The PAN card photo is blurry or cropped. Please retake it in good light with all four corners visible.'
};
const issues = f.validation_errors.concat(f.rule_flags.filter(x => friendly[x]).map(x => friendly[x]));
const issuesHtml = '<ul>' + issues.map(i => '<li>' + esc(i) + '</li>').join('') + '</ul>';

return {
  json: {
    application_id: f.application_id,
    full_name: f.full_name,
    first_name: f.first_name,
    email: f.email,
    decision: decision,
    decision_reason: reason,
    risk_level: level,
    final_risk_score: finalScore,
    rule_score: f.rule_score,
    ai_risk_score: aiAvailable ? aiScore : null,
    ai_recommendation: ai.recommended_action || 'UNAVAILABLE',
    flags_text: f.rule_flags.join(', ') || 'none',
    rationale: ai.rationale || reason,
    customer_message: ai.customer_safe_message || 'Thank you for your application.',
    issues_html: issuesHtml,
    reviewer_html: reviewerHtml,
    straight_through: decision === 'AUTO_APPROVE',
    processing_ms: processingMs
  }
};
